INSERT INTO ca_import VALUES
('1.1','Percussion Musical Instruments (Drawing)',17,1,ARRAY['Recognise percussion instruments used by Kenyan communities.','Group indigenous percussion instruments by how they produce musical sounds.','Describe the purpose of the different parts of percussion instruments.','Create rhythmic accompaniments with local percussion instruments.','Prepare charcoal sticks safely for drawing.','Use charcoal and smudging to show tonal variation in a percussion instrument drawing.','Respect musical traditions and classmates'' drawings.']::text[]),
('1.2','Netball',15,2,ARRAY['Explain netball passing and catching techniques.','Make a ball using an overhand-knot macramé method.','Demonstrate chest and overhead passes and two-handed catches.','Participate positively in team netball.']::text[]),
('1.3','Painting and Montage',15,3,ARRAY['Distinguish primary and secondary colours.','Paint simple objects using variations in colour value.','Assemble an expressive picture montage.','Value painting and montage as visual communication.']::text[]),
('1.4','Rhythm',15,4,ARRAY['Read crotchets, pairs of quavers and their rests in rhythmic patterns.','Letter French rhythm names neatly by hand.','Describe characteristics of an effective rhythm.','Compose rhythms using the studied notes and rests.','Take pleasure in making original rhythmic patterns.']::text[]),
('1.5','Melody',15,5,ARRAY['Recognise the sol-fa pitches do, re and mi in simple melodies.','Use Kodály hand signs to distinguish the three pitches.','Identify characteristics of a well-formed melody.','Compose short melodies using do, re and mi.','Model clay slabs and coil letters for sol-fa syllables.','Enjoy creating melodies and clay models.']::text[]),
('2.1','Athletics',18,6,ARRAY['Explain medium and elongated sprint starts and running technique.','Perform sprint starts and sprinting safely.','Paint a Kenyan flag for an athletics occasion.','Explain the significance of displaying Kenya''s flag at sporting events.']::text[]),
('2.2','Gymnastics',15,7,ARRAY['Describe the crab balance and side roll.','Demonstrate a controlled crab balance.','Perform a safe side roll.','Value gymnastics for fitness and enjoyment.']::text[]),
('2.3','Songs',15,8,ARRAY['Sing different song types with appropriate pitch, rhythm and expression.','Perform the East African Community anthem together.','Identify kinds of folk songs from Kenyan communities.','Perform a Kenyan folk song with suitable technique.','Show respect for indigenous songs from different communities.']::text[]),
('2.4','Photography',10,9,ARRAY['Identify digital devices that can take photographs.','Discuss light and the centre of interest in photography.','Take expressive photographs using digital devices.','Enjoy photography while caring for equipment.']::text[]),
('2.5','Descant Recorder',15,10,ARRAY['Identify the main parts of a descant recorder.','Clean, handle and store a recorder appropriately.','Play the notes B, A and G using correct technique.','Perform short melodies with B, A and G.','Enjoy making music with a descant recorder.']::text[]),
('2.6','Swimming',15,11,ARRAY['Recognise safe methods of entering a swimming pool.','Join supervised water games safely.','Practise floating in water.','Practise gliding to build water confidence.','Follow water-safety precautions in and around pools.']::text[]),
('2.6','Indigenous Kenyan Games',15,12,ARRAY['Identify indigenous Kenyan animal games.','Demonstrate skills used in animal games.','Perform animal games to a musical beat.','Explain how animal games support fitness and health.']::text[]),
('3.1','Analysis of Creative Arts Works',15,13,ARRAY['Explain how to appreciate creative work constructively.','Prepare a portfolio for presenting artworks.','Display and discuss one''s own and peers'' artwork respectfully.','Analyse the meaning and patriotic role of the Kenya National Anthem.','Describe features of a Kenyan folk-song performance using musical vocabulary.','Participate safely in school games and sports.','Appreciate creative work from different cultural backgrounds.']::text[]);
