-- Grade 4 Creative Arts, KICD revised 2024, VibeSchool-original outcome paraphrases.
-- KICD copyright reserved; no claim that these are verbatim official outcomes.
-- Summary gives Photography 10 lessons; detail gives 8; summary used, discrepancy retained.
-- Swimming and Indigenous Kenyan Games are alternatives: teach exactly one.
BEGIN;
CREATE TEMP TABLE ca_import(code text,title text,lessons int,seq int,outcomes text[]) ON COMMIT DROP;
DO $$ BEGIN IF (SELECT count(*) FROM ca_import)<>13 OR (SELECT sum(cardinality(outcomes)) FROM ca_import)<>64 THEN RAISE EXCEPTION 'CA completeness check failed'; END IF; END $$;
SELECT '6d68b57c-565d-4a04-879d-c77f588d6404'::uuid,'Grade 4',CASE left(code,1) WHEN '1' THEN 'Creating and Executing' WHEN '2' THEN 'Performing and Displaying' ELSE 'Appreciation in Creative Arts' END,code||' '||title,left(code,1)::int,seq,outcomes,'https://cbcelimu.com/wp-content/uploads/2024/12/Grade-4-Creative-Arts-Curriculum-Design-May-2024-final.pdf#owner-paraphrase-2026-11-22'
FROM ca_import r WHERE NOT EXISTS (SELECT 1 FROM public.cbc_strands s WHERE s.subject_id='6d68b57c-565d-4a04-879d-c77f588d6404'::uuid AND s.grade='Grade 4' AND s.sub_strand=r.code||' '||r.title);
SELECT s.id,o.outcome,r.code||'.'||o.ordinality,'generated','https://cbcelimu.com/wp-content/uploads/2024/12/Grade-4-Creative-Arts-Curriculum-Design-May-2024-final.pdf#vibeschool-paraphrase-2026-11-22','active','Grade 4 Creative Arts / '||r.code||' / '||r.title
FROM ca_import r JOIN public.cbc_strands s ON s.subject_id='6d68b57c-565d-4a04-879d-c77f588d6404'::uuid AND s.grade='Grade 4' AND s.sub_strand=r.code||' '||r.title
CROSS JOIN LATERAL unnest(r.outcomes) WITH ORDINALITY o(outcome,ordinality)
WHERE NOT EXISTS(SELECT 1 FROM public.curriculum_learning_outcomes e WHERE e.sub_strand_id=s.id AND e.outcome_text=o.outcome);
DO $$ DECLARE n int; m int; BEGIN SELECT count(*) INTO n FROM public.cbc_strands WHERE subject_id='6d68b57c-565d-4a04-879d-c77f588d6404'::uuid AND grade='Grade 4' AND source_ref='https://cbcelimu.com/wp-content/uploads/2024/12/Grade-4-Creative-Arts-Curriculum-Design-May-2024-final.pdf#owner-paraphrase-2026-11-22'; SELECT count(*) INTO m FROM public.curriculum_learning_outcomes WHERE source_ref='https://cbcelimu.com/wp-content/uploads/2024/12/Grade-4-Creative-Arts-Curriculum-Design-May-2024-final.pdf#vibeschool-paraphrase-2026-11-22'; IF n<>13 OR m<>64 THEN RAISE EXCEPTION 'CA postcheck failed: % entries % outcomes',n,m; END IF; END $$;
COMMIT;
